'use client';

import { OpenfortProvider, AuthProvider } from '@openfort/react';
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { baseSepolia, base } from 'viem/chains';
import { createConfig, WagmiProvider } from 'wagmi';
import type { ReactNode } from 'react';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;

const wagmiConfig = createConfig(
  getDefaultConfig({
    appName: 'InfraFund',
    chains: [baseSepolia, base],
    walletConnectProjectId:
      process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || '',
  })
);

const queryClient = new QueryClient();

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={publishableKey}
            walletConfig={{
              shieldPublishableKey,
              ethereum: {
                ethereumFeeSponsorshipId:
                  process.env.NEXT_PUBLIC_POLICY_ID || undefined,
              },
              connectOnLogin: true,
              createEncryptedSessionEndpoint: '/api/auth/encryption-session',
            }}
            uiConfig={{
              theme: 'midnight',
              mode: 'dark',
              authProviders: [
                AuthProvider.GOOGLE,
                AuthProvider.EMAIL_OTP,
                AuthProvider.WALLET,
              ],
            }}
          >
            {children}
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  );
}

'use client';

import React, { useEffect } from 'react';
import { useUser } from '@openfort/react';
import { OpenfortButton } from '@openfort/react';
import { useRouter } from 'next/navigation';
import infrafund from '@/../public/assets/svg/infrafund.svg';
import Image from 'next/image';

export default function Login() {
  const router = useRouter();
  const { user, isAuthenticated } = useUser();

  useEffect(() => {
    if (isAuthenticated && user) {
      router.push('/home');
    }
  }, [isAuthenticated, user, router]);

  return (
    <div className="w-full flex justify-center items-center">
      <div className="flex flex-col items-center gap-8 p-8">
        <Image src={infrafund} alt="InfraFund" />
        <OpenfortButton />
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from 'next/server';

const SHIELD_URL = process.env.SHIELD_URL || 'https://shield.openfort.io';
const SHIELD_PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
const SHIELD_SECRET_KEY = process.env.SHIELD_SECRET_KEY;
const SHIELD_ENCRYPTION_SHARE = process.env.SHIELD_ENCRYPTION_SHARE;

export async function POST(request: NextRequest) {
  if (!SHIELD_PUBLISHABLE_KEY || !SHIELD_SECRET_KEY || !SHIELD_ENCRYPTION_SHARE) {
    return NextResponse.json(
      { message: 'Shield credentials not configured on server' },
      { status: 500 }
    );
  }

  try {
    const body = await request.json();

    const response = await fetch(`${SHIELD_URL}/project/encryption-session`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': SHIELD_PUBLISHABLE_KEY,
        'x-api-secret': SHIELD_SECRET_KEY,
      },
      body: JSON.stringify({
        encryption_part: SHIELD_ENCRYPTION_SHARE,
        user_id: body.user_id,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('Shield encryption session error:', error);
      return NextResponse.json(
        { message: 'Failed to create encryption session' },
        { status: response.status }
      );
    }

    const data = await response.json();
    return NextResponse.json({ session: data.session_id });
  } catch (err) {
    console.error('Encryption session error:', err);
    return NextResponse.json(
      { message: 'Internal server error' },
      { status: 500 }
    );
  }
}

