/// <reference types="next" />
/// <reference types="next/image-types/global" />
/// <reference path="./.next/types/routes.d.ts" />

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

import { AxiosRequestConfig } from 'axios';
import _axios from '../utils/axios.utils';
import { getAccessToken } from '@/utils/get-access-token.util';

interface ApiService {
  get: <T>(url: string, params?: AxiosRequestConfig) => Promise<T>;
  post: <T>(url: string, data?: object) => Promise<T>;
  put: <T>(url: string, data: object) => Promise<T>;
  patch: <T>(url: string, data: object) => Promise<T>;
}

function reWriteUrl(url: string): string {
  return `api${url}`;
}

async function getAxiosRequestConfig(): Promise<AxiosRequestConfig> {
  const token = getAccessToken();
  return {
    headers: {
      Authorization: token ? `Bearer ${token}` : '',
      Accept: 'application/json',
      Expires: '0',
    },
  };
}

const apiService: ApiService = {
  get: async <T>(url: string, params = {}): Promise<T> => {
    try {
      const response = await _axios.get<T>(reWriteUrl(url), params);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  post: async <T>(url: string, data?: object): Promise<T> => {
    try {
      const response = await _axios.post<T>(reWriteUrl(url), data);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  put: async <T>(url: string, data: object): Promise<T> => {
    try {
      const response = await _axios.put<T>(reWriteUrl(url), data);
      return response.data;
    } catch (error) {
      throw error;
    }
  },

  patch: async <T>(url: string, data: object): Promise<T> => {
    try {
      const response = await _axios.patch<T>(reWriteUrl(url), data);
      return response.data;
    } catch (error) {
      throw error;
    }
  },
};

export default apiService;

import { NextRequest, NextResponse } from 'next/server';

const SHIELD_URL = process.env.SHIELD_URL || 'https://shield.openfort.io';
const SHIELD_PUBLISHABLE_KEY = process.env.NEXT_PUBLIC_SHIELD_API_KEY;
const SHIELD_SECRET_KEY = process.env.SHIELD_SECRET_KEY;
const SHIELD_ENCRYPTION_SHARE = process.env.SHIELD_ENCRYPTION_SHARE;

export async function POST(request: NextRequest) {
  if (!SHIELD_PUBLISHABLE_KEY || !SHIELD_SECRET_KEY || !SHIELD_ENCRYPTION_SHARE) {
    return NextResponse.json(
      { message: 'Shield credentials not configured on server' },
      { status: 500 }
    );
  }

  try {
    const body = await request.json();

    const response = await fetch(`${SHIELD_URL}/project/encryption-session`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': SHIELD_PUBLISHABLE_KEY,
        'x-api-secret': SHIELD_SECRET_KEY,
      },
      body: JSON.stringify({
        encryption_part: SHIELD_ENCRYPTION_SHARE,
        user_id: body.user_id,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      console.error('Shield encryption session error:', error);
      return NextResponse.json(
        { message: 'Failed to create encryption session' },
        { status: response.status }
      );
    }

    const data = await response.json();
    return NextResponse.json({ session: data.session_id });
  } catch (err) {
    console.error('Encryption session error:', err);
    return NextResponse.json(
      { message: 'Internal server error' },
      { status: 500 }
    );
  }
}

