      id: (lastId + 1).toString(),
      question: '',
      answer: '',
    };
    setFaqs([...faqs, newFaq]);
  };

  const removeFaq = (id: string) => {
    setRemovingId(id);
    setTimeout(() => {
      setFaqs((prev) => prev.filter((faq) => faq.id !== id));
      setRemovingId(null);
    }, 300);
  };

  const updateFaq = (id: string, field: keyof Question, value: string) => {
    setFaqs(
      faqs.map((faq) => (faq.id === id ? { ...faq, [field]: value } : faq))
