package middleware

import (
	"strings"

	"github.com/InfraFund-net7/backpro/internal/common/types/auth"
	"github.com/InfraFund-net7/backpro/internal/common/types/key"
	"github.com/InfraFund-net7/backpro/pkg/crypto"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/danielgtaylor/huma/v2"
)

type AuthMiddleware struct {
	aut       *crypto.JWT
	api       huma.API
	headerKey string
}

func NewAuthMiddleware(api huma.API, aut *crypto.JWT) *AuthMiddleware {
	return &AuthMiddleware{
		aut:       aut,
		api:       api,
		headerKey: "Authorization",
	}
}

// Auth request after authorization.
func (a *AuthMiddleware) Auth() func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		claim, err := a.validateRequest(ctx)
		if err != nil {
			_ = huma.WriteErr(a.api, ctx, 401, err.Error())

			return
		}

		a.setAuthInfo(ctx, claim, next)
	}
}

// AuthRoles allowed request with specified roles to resource.
func (a *AuthMiddleware) AuthRoles(roles ...string) func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		claim, err := a.validateRequest(ctx)
		if err != nil {
			_ = huma.WriteErr(a.api, ctx, 401, err.Error())

			return
		}

		if len(roles) != 0 {
			allowed := false
			for _, role := range roles {
				if role == claim.Role {
					allowed = true

					break
				}
			}

			if !allowed {
				_ = huma.WriteErr(a.api, ctx, 403, "you don't have access to this resource")

				return
			}
		}

		a.setAuthInfo(ctx, claim, next)
	}
}

// AuthOptional allowed request with limited resource info.
func (a *AuthMiddleware) AuthOptional() func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		token := a.extractAuthorizationBearerKey(ctx)
		if token == "" {
			next(ctx)

			return
		}

		claim, err := a.aut.VerifyAccessToken(token)
		if err != nil {
			_ = huma.WriteErr(a.api, ctx, 401, err.Error())

			return
		}

		a.setAuthInfo(ctx, claim, next)
	}
}

func (a *AuthMiddleware) setAuthInfo(ctx huma.Context, claim *crypto.Claim, next func(huma.Context)) {
	authInfo, err := auth.NewUserInfo(claim)
	if err != nil {
		_ = huma.WriteErr(a.api, ctx, 401, err.Error())

		return
	}

	ctx = huma.WithValue(ctx, key.AuthorizedUserInfoKey, authInfo)

	next(ctx)
}

func (a *AuthMiddleware) validateRequest(ctx huma.Context) (*crypto.Claim, error) {
	token := a.extractAuthorizationBearerKey(ctx)
	if token == "" {
		return nil, errs.NewAppError(errs.Unauthorized, "missing authorization header", 401)
	}

	claim, err := a.aut.VerifyAccessToken(token)
	if err != nil {
		return nil, errs.NewAppError(errs.Unauthorized, err.Error(), 401)
	}

	return claim, nil
}

func (*AuthMiddleware) extractAuthorizationBearerKey(ctx huma.Context) string {
	authHeader := ctx.Header("Authorization")
	if authHeader == "" {
		return ""
	}

	const bearerPrefix = "Bearer "
	if !strings.HasPrefix(authHeader, bearerPrefix) {
		return ""
	}

	token := strings.TrimSpace(authHeader[len(bearerPrefix):])
	if token == "" {
		return ""
	}

	return token
}

