	"github.com/InfraFund-net7/backpro/pkg/logger"
)

var _ service.JwtService = (*JwtService)(nil)

type JwtService struct {
	jwt *crypto.JWT

	logger *logger.SubLogger
}

func NewJwtService(cfg *crypto.Config) (*JwtService, error) {
	jw, err := crypto.New(cfg)
	if err != nil {
		return nil, err
	}

	return &JwtService{
		jwt:    jw,
		logger: logger.NewBusinessLogger("jwt"),
	}, nil
}

func (s *JwtService) GenerateToken(claim *entity.JwtClaim) (string, error) {
	token, err := s.jwt.GenerateAccessToken(crypto.Claim{
		UserID:      claim.UserID,
		SessionID:   claim.SessionID,
		KycVerified: claim.KycVerified,
		KybVerified: claim.KybVerified,
		Role:        claim.Role.String(),
		Type:        claim.Type.String(),
	})
	if err != nil {
		s.logger.Error("failed to generate token", "error", err.Error(), "claim", claim)

		return "", errs.NewAppError(errs.Internal, "failed to generate access token", 500)
	}

	return token, nil
}

func (s *JwtService) VerifyToken(token string) (*entity.JwtClaim, error) {
	claim, err := s.jwt.VerifyAccessToken(token)
	if err != nil {
		s.logger.Error("failed to verify token", "error", err.Error())

		return nil, errs.NewAppError(errs.Unauthorized, "failed to verify token", 401)
	}

	return &entity.JwtClaim{
		UserID:      claim.UserID,
		SessionID:   claim.SessionID,
		KycVerified: claim.KycVerified,
		KybVerified: claim.KybVerified,
		Role:        object.UserRole(claim.Role),
		Type:        object.UserType(claim.Type),
	}, nil
}

